from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Entre 1499 y 1554 aparecen dos obras que cambian el rumbo de la narrativa en castellano: La Celestina, una obra dialogada que es a la vez drama y novela, y el Lazarillo de Tormes, relato autobiográfico y anónimo que funda la novela picaresca. Ambas descubren la prosa realista, el interés por los marginados y una mirada crítica sobre la sociedad.',
        quotes=[Q('es_celestina','La Celestina es el nombre con el que se ha popularizado la Tragicomedia de Calisto y Melibea'), Q('en_lazarillo','Lazarillo de Tormes is the first book establishing the style of the picaresque satirical novel.')]))
    P.append(dict(text='La Celestina se atribuye a Fernando de Rojas, bachiller nacido en La Puebla de Montalbán que estudió en Salamanca. Rojas declara en un texto preliminar que encontró un esbozo anónimo, que se identifica con el primer acto, y lo continuó. Su composición se remonta a los últimos años del siglo XV, durante el reinado de los Reyes Católicos, y su enorme éxito editorial se prolongó hasta su prohibición en 1792. Es una obra «sui generis»: por su forma dialogada y su probable vinculación al ambiente universitario se la ha considerado una comedia humanística, pero también un híbrido entre novela y drama.',
        quotes=[Q('es_celestina','Su composición se remonta a los últimos años del siglo XV','hasta su prohibición en 1792'), Q('en_celestina','it is attributed to Fernando de Rojas, a descendant of converted Jews')]))
    P.append(dict(text='La historia editorial es compleja. La primera versión impresa es la Comedia de Calisto y Melibea, de dieciséis actos, de la que se conocen tres ediciones, entre ellas la de Burgos atribuida a Fadrique de Basilea en 1499 (aunque la fecha es discutida) y la de Toledo de 1500. La segunda versión, la Tragicomedia, añade cinco actos entre el catorce y el diecinueve y alcanza los veintiún actos; se conocen más de cien ediciones en castellano. Más tarde se añadió incluso un Acto de Traso, que lleva el total a veintidós en una edición de Toledo de 1526.',
        quotes=[Q('es_celestina','Se caracteriza por tener veintiún actos','cinco actos adicionales insertos entre el acto catorce y diecinueve'), Q('es_celestina','se conocen más de cien ediciones en castellano'), Q('en_celestina','There are two versions of the play. One is called a Comedy and has 16 acts; the other is considered a Tragic Comedy and has 21 acts.')]))
    P.append(dict(text='El argumento es sencillo. Calisto, un joven noble, se enamora de Melibea, una muchacha recluida por sus padres, y recurre a la vieja alcahueta Celestina para conseguir su amor. Los criados de Calisto, Pármeno y Sempronio, se asocian con ella por interés y acaban matándola por la codicia. Calisto muere al caer de una escala al salir del jardín de Melibea, y esta se arroja desde una torre. El desenlace trágico responde a una intención moralizante: el naturalismo crudo de la obra solo era soportable, según los criterios de la época, si los culpables eran castigados.',
        quotes=[Q('en_celestina','The story tells of a bachelor, Calisto, who uses the old procuress and bawd Celestina to start an affair with Melibea'), Q('es_celestina','el crudo naturalismo de que hace gala solo era soportable según los criterios de la época','debidamente castigados')]))
    P.append(dict(text='Lo más moderno de La Celestina son sus personajes. Celestina, Sempronio, Pármeno, Elicia y Areúsa no son héroes ni santos, sino gente del común movida por el interés. Se ha visto en Calisto el nuevo estilo de vida de una clase ociosa, y en Sempronio y Pármeno la ruptura de los lazos feudales. El diálogo, que sustituye a la narración, permite que cada personaje se defina por su propia voz, y esa forma ha hecho que la crítica hable de un género celestinesco que alcanza a muchas comedias y novelas posteriores.',
        quotes=[Q('es_celestina','Calisto representaría el nuevo estilo de vida de la clase ociosa','los lazos feudales'), Q('en_celestina','is a work entirely in dialogue published in 1499')]))
    P.append(dict(text='El Lazarillo de Tormes es una novela anónima, escrita en primera persona y en forma epistolar, cuyas ediciones más antiguas datan de 1554. Se conservan cuatro ediciones de ese año, impresas en Burgos, Amberes, Alcalá de Henares y Medina del Campo, aunque es probable que hubiera otra anterior. Cuenta de forma autobiográfica la vida de Lázaro desde su miserable infancia hasta su matrimonio, en siete tratados, y es en realidad una larga carta a un corresponsal al que llama «Vuestra Merced», que le pide explicar «el caso».',
        quotes=[Q('es_lazarillo','es una novela española anónima, escrita en primera persona y en estilo epistolar'), Q('en_lazarillo','The earliest known editions are the four of Alcalá de Henares, Antwerp, Medina del Campo, and Burgos, all of which appeared in 1554.')]))
    P.append(dict(text='Lázaro sirve a una serie de amos —un ciego, un clérigo avaro, un escudero arruinado y otros— que le enseñan a sobrevivir. El hambre, la hipocresía y la honra vacía son los motores del relato, y a través del servicio a varios amos se ofrece un retrato irónico y despiadado de la sociedad del momento, sobre todo de los clérigos y religiosos. La estructura itinerante, la narración en primera persona, el realismo y la ideología moralizante y pesimista son los rasgos que hacen del Lazarillo el precursor de la novela picaresca.',
        quotes=[Q('es_lazarillo','Esta obra es considerada precursora de la novela picaresca','pesimista.'), Q('en_lazarillo','In novels of this type, the adventures of the pícaro expose injustice while amusing the reader.')]))
    P.append(dict(text='La obra se publicó anónima por su contenido anticlerical y su autor probablemente simpatizaba con las ideas de Erasmo de Róterdam. La Inquisición la incluyó en el Índice de libros prohibidos y más tarde permitió una versión expurgada de los pasajes anticlericales; no volvió a publicarse íntegramente hasta el siglo XIX. Se han propuesto varios autores, entre ellos fray Juan de Ortega, a quien atribuyó la obra en 1605 el fraile José de Sigüenza, pero ninguna atribución ha obtenido consenso.',
        quotes=[Q('es_lazarillo','Como consecuencia, resultó la inclusión de esta obra en el Índice de libros prohibidos de la Inquisición'), Q('en_lazarillo','published anonymously because of its anticlerical content')]))
    P.append(dict(role='definition', text='Novela picaresca: género narrativo nacido con el Lazarillo, en el que un pícaro cuenta en primera persona su vida como servidor de varios amos, con un tono realista y crítico que pone al descubierto la injusticia social mientras entretiene al lector.',
        quotes=[Q('en_lazarillo','Lazarillo de Tormes is credited with founding a literary genre, the picaresque novel'), Q('es_lazarillo','el realismo, la narración en primera persona, la estructura itinerante, el servicio a varios amos')]))
    P.append(dict(role='consejo', text='Para comparar La Celestina y el Lazarillo, fíjese en quién habla: en la primera, cada personaje se expresa en diálogo directo y el autor desaparece; en el segundo, un único narrador se justifica ante «Vuestra Merced» y selecciona los hechos de su vida. Esa diferencia de voz explica casi todas las diferencias de enfoque.',
        quotes=[Q('en_celestina','is a work entirely in dialogue published in 1499'), Q('es_lazarillo','Es epistolar en tanto se trata de una carta destinada a «vuestra merced»')]))
    P.append(dict(role='self_check', text='¿Qué diferencias hay entre la Comedia y la Tragicomedia de Calisto y Melibea? ¿Por qué se publicó el Lazarillo de forma anónima y por qué lo prohibió la Inquisición? ¿Qué rasgos del Lazarillo se convertirán en convenciones de la novela picaresca?',
        quotes=[Q('en_celestina','This version contained 5 additional acts, bringing the total to 21.'), Q('es_lazarillo','Esto motivó que la Inquisición la prohibiera')]))
    return P

def _legacy_numeric_problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='La Comedia de Calisto y Melibea tiene dieciséis actos y la Tragicomedia añade cinco más. Calcule cuántos actos tiene la Tragicomedia y en qué porcentaje aumentó el número de actos respecto de la Comedia.',
        expected='31.25', quotes=[Q('en_celestina','This version contained 5 additional acts, bringing the total to 21.'), Q('es_celestina','Se caracteriza por tener dieciséis actos')],
        method='Suma de actos y variación porcentual relativa',
        solution=dict(given=[dict(symbol='A_C',value=16,unit='dimensionless',meaning='actos de la Comedia'),dict(symbol='a',value=5,unit='dimensionless',meaning='actos añadidos')],
          unknown='El número de actos de la Tragicomedia y el aumento porcentual.',
          model=[dict(name='Actos de la Tragicomedia',latex='A_T = A_C + a',symbolic='A_C + a'),dict(name='Variación porcentual',latex='\\Delta = 100\\,\\frac{a}{A_C}',symbolic='100*a/A_C')],
          assumptions=['Se comparan solo las dos versiones principales; no se cuenta el Acto de Traso, que solo aparece en algunas ediciones posteriores.'],
          development=['La variación relativa se refiere al número de actos de la versión de partida.'],
          steps=[dict(text='Actos de la Tragicomedia',equation='A_T = 16 + 5',expression='16+5',expected=21,unit='dimensionless'),
                 dict(text='Aumento porcentual',equation='\\Delta = 100 \\cdot 5/16',expression='100*5/16',expected=31.25,unit='dimensionless')],
          result='La Tragicomedia tiene 21 actos, un 31,25 % más que la Comedia.',
          interpretation='Rojas amplió casi un tercio la obra, pero las ampliaciones no son meros añadidos: el cambio de título refleja una nueva concepción de la obra como tragicomedia.',
          limitations=['El porcentaje depende de contar el Acto de Traso o no; con él la Tragicomedia llegaría a 22 actos en algunas ediciones.'],
          mistakes=['Dividir por 21 en lugar de por 16 al calcular el aumento relativo.']))]


