HEADS = {1: 'Fernando de Rojas', 2: 'Del manuscrito a la Tragicomedia', 3: 'Un argumento sencillo', 4: 'Personajes con vida propia', 5: 'Un pícaro escribe una carta', 6: 'Siete amos', 7: 'Una novela anónima'}


def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='Los «papeles del viejo autor»\nLos preliminares de La Celestina dicen que el autor encontró un esbozo de la obra, que adoptó sin cambios y que constituye el primer acto. Aunque se ha discutido la veracidad de la afirmación, existe cierto consenso y estudios que apoyan la independencia del primer acto. No hay unanimidad sobre su autor, aunque los nombres más repetidos han sido Rodrigo Cota y Juan de Mena, por la mención de ambos en las octavas acrósticas. Hoy se tiende a pensar que esa alusión es solo encomiástica. De ahí que el problema de la autoría de La Celestina tenga varias respuestas: autoría doble (el viejo autor y Rojas), única, triple, colectiva, entre otras.',
        quotes=[Q('es_celestina', 'se afirma que el autor encontró un esbozo de la obra, que adoptó sin cambios y que constituye el primer acto de su propio texto'), Q('es_celestina', 'los autores a los que con mayor recurrencia se les ha atribuido este primer acto han sido Rodrigo Cota'), Q('es_celestina', 'La hipótesis de la autoría triple tradicional es la que atribuye los «papeles del antiguo autor», la Comedia y la ampliación a Tragicomedia a tres manos diferentes.'), Q('en_celestina', 'Although most scholars admit that an earlier version by an unknown author already existed')]))
    P.append(dict(text='Comedia y Tragicomedia\nLa Comedia de Calisto y Melibea, primera versión impresa, tiene dieciséis actos, y la Tragicomedia, veintiuno: se añaden cinco actos entre el catorce y el diecinueve. Las dos fuentes lo dicen, pero discrepan en las fechas. La fuente inglesa considera que la primera edición conocida es la de Burgos, Fadrique de Basilea, de 1499, y que la Tragicomedia apareció en Sevilla en 1502; la fuente española advierte que la edición de Burgos ha sido manipulada, que su credibilidad como editio princeps está en entredicho y que la edición más antigua de la Tragicomedia con ejemplares conservados es la de Zaragoza, 1507. Ambas coinciden en que la primera edición no pudo ser posterior a 1500. Este es un caso real de fuentes que se contradicen y que el historiador de la literatura debe contrastar.',
        quotes=[Q('es_celestina', 'Se caracteriza por tener dieciséis actos'), Q('es_celestina', 'Se caracteriza por tener veintiún actos'), Q('es_celestina', 'La edición más antigua de la Tragicomedia con ejemplares conservados es la de Jorge Coci, Zaragoza, 1507.'), Q('en_celestina', 'the first known edition is credited to be the Comedy published in Burgos by printer Fadrique de Basilea in 1499'), Q('en_celestina', 'A new edition entitled Tragicomedia de Calisto y Melibea (Tragic Comedy of Calisto and Melibea) (Seville: Jacobo Cromberger) appeared in 1502.')]))
    P.append(dict(text='El «Auto de Centurio» y el título\nLa gran interpolación entre los actos catorce y diecinueve se llama «Auto de Centurio». Según el prólogo en prosa, responde al deseo de los lectores de que los amantes disfrutaran más tiempo de sus amores; en realidad, ofrece un retrato más detallado de la vida prostibularia y rufianesca, con Elicia, Areúsa y Centurio. Esa versión popularizó el texto en Europa: en 1506 apareció en Roma una traducción al italiano. En 1526 se imprimió en Toledo una versión de veintidós actos con el «Auto de Traso», que según su argumento procede de una comedia de un tal Sanabria. El título «La Celestina» nace en Italia, en la edición veneciana de Arrivabene de 1519; las ediciones españolas mantienen casi un siglo el de Tragicomedia de Calisto y Melibea.',
        quotes=[Q('es_celestina', 'La gran interpolación entre los actos catorce y diecinueve es denominada, tradicionalmente, «Auto de Centurio»'), Q('es_celestina', 'La traducción italiana de Alphonso Hordognez fue impresa por primera vez como la Tragicocomedia di Calisto e Melibea por Eucario Silber, Roma, 1506.'), Q('es_celestina', 'El impresor Ramón de Petras imprime en Toledo en 1526 una versión de la Tragicomedia con veintidós actos.'), Q('es_celestina', 'la tradición de utilizar el nombre de la alcahueta en portada se origina en Italia, más concretamente en la edición de la traducción italiana de la Tragicomedia de Cesare Arrivabene, Venecia, 1519'), Q('en_celestina', 'This version contained 5 additional acts, bringing the total to 21.')]))
    P.append(dict(text='¿Quién escribió La Celestina?\nEn las ediciones antiguas no aparece ningún nombre de autor en portada hasta 1632. Las octavas acrósticas la ponen en relación con un bachiller Fernando de Rojas, nacido en La Puebla de Montalbán. En 1902 se exhumaron procesos inquisitoriales que citan a un Fernando de Rojas histórico como «el que compuso a La Celestina», y los estudiosos construyeron su biografía: la fuente inglesa lo describe como descendiente de judíos conversos que ejerció la abogacía y fue alcalde de Talavera de la Reina. Pero en tiempos más recientes han surgido dudas sobre esa identificación: no concuerda el perfil intelectual del Rojas histórico con el del autor, y los verbos «acabar» y «componer» describen relaciones distintas con el texto. La autoría sigue discutida.',
        quotes=[Q('es_celestina', 'En las ediciones antiguas de La Celestina no aparece ningún nombre del autor en portada hasta la edición expurgada de 1632.'), Q('es_celestina', 'A raíz de la exhumación en 1902 de una serie de procesos inquisitoriales que hacen referencia a un Fernando de Rojas histórico'), Q('en_celestina', 'it is attributed to Fernando de Rojas, a descendant of converted Jews, who practiced law'), Q('es_celestina', 'en tiempos más recientes han surgido serias dudas sobre la pertinencia de esta identificación')]))
    P.append(dict(text='¿Novela o teatro?\nEl género de La Celestina es un problema desde sus orígenes, como denuncia el propio autor en el prólogo. Por su extensión y su irrepresentabilidad, y porque estaba escrita en forma de diálogo, los teóricos neoclásicos inventaron el término «novela dramática», que Moratín consagró en sus Orígenes del teatro español. La fuente inglesa dice que, aunque suele considerarse una novela, está escrita como una serie continua de diálogos. En el siglo XX, Whinnom, Deyermond y Severin revisaron los argumentos y la definieron como «novela dialogada». Los títulos «comedia» y «tragicomedia» alejan de esa discusión: el primero porque el desenlace es feliz solo en la forma, el segundo porque el final es trágico.',
        quotes=[Q('es_celestina', 'La cuestión del género de La Celestina es un problema desde sus propios orígenes'), Q('es_celestina', 'obliga a los teóricos neoclásicos a inventar el término «novela dramática»'), Q('es_celestina', 'la definición de La Celestina como «novela dialogada» conoce un resurgimiento'), Q('en_celestina', 'Although usually regarded as a novel, it is written as a continuous series of dialogues')]))
    P.append(dict(text='Qué quería decir Rojas\nEl autor señala tres temas: la corrupción de los sirvientes que degradan a sus amos, la prevención contra el loco amor que lleva a los amantes a creer que sus amadas son su dios y un tema filosófico más profundo. La crítica discute la intención. Para Bataillon, la moral cristiana domina toda la obra; para Lida de Malkiel, es ante todo fruto de una voluntad artística, y la intención didáctica pasó desapercibida a los lectores; Otis Green propone una tesis ecléctica que admite la intención moral y explica lo artístico; Maravall ve a los protagonistas a la luz de las transformaciones de la sociedad, con Calisto como la clase ociosa y Sempronio y Pármeno como la ruptura de los lazos feudales. Hay quien destaca el pesimismo: el final mortal de los personajes.',
        quotes=[Q('es_celestina', 'Hay tres temas principales en la obra, señalados por el propio autor'), Q('es_celestina', 'Esta tesis ha sido sostenida por Marcel Bataillon, que piensa que la moral cristiana domina toda la obra'), Q('es_celestina', 'Sostenida por Lida de Malkiel, quien no niega el fondo moralista'), Q('es_celestina', 'Calisto representaría el nuevo estilo de vida de la clase ociosa'), Q('en_celestina', 'Though the two use the rhetoric of courtly love, sex — not marriage — is their aim.')]))
    P.append(dict(text='Una sociedad que cambia\nLa Celestina se escribe durante el reinado de los Reyes Católicos, entre 1469 y 1504, la última fase del Prerrenacimiento, y en ella se muestran las características de una Edad Media que se termina para dar paso al Renacimiento. Los sirvientes, que en la Edad Media trabajaban por la manutención y la defensa, exigen a Calisto que les pague; el noble Calisto no ejerce las armas y vive en el ocio; y el padre de Melibea basa sus riquezas en lo material y no en la tierra. La fuente inglesa lo sitúa en el mismo marco: la unión de las coronas, la unificación de los territorios de la Península bajo una sola religión y la importancia de ser cristiano viejo en una sociedad que desconfiaba de los miembros de otras religiones.',
        quotes=[Q('es_celestina', 'La Celestina se escribe durante el reinado de los Reyes Católicos'), Q('es_celestina', 'en La Celestina le exigen a Calisto que les pague'), Q('es_celestina', 'Calisto no tiene el ejercicio de las armas, limitándose a una vida de ocio'), Q('en_celestina', 'La Celestina was written during the reign of Ferdinand and Isabella, whose marriage took place in 1469')]))
    P.append(dict(text='La estructura: causas y consecuencias\nLa división en actos no tiene verdadero significado estructural; atendiendo a la acción, la obra se divide en un prólogo, el encuentro de Calisto y Melibea, y dos partes: la intervención de Celestina y los criados, con la muerte de los tres y la primera noche de amor, y la venganza, con la segunda noche, la muerte de Calisto, el suicidio de Melibea y el llanto de Pleberio. La crítica señala una estricta motivación realista y una cadena de causa y efecto: el patrón de la «cuenta presentada» de Lukács, según el cual más tarde o más temprano hay que pagar por los actos. Otro principio de orden es la anticipación del final: todos los símbolos se ordenan hacia el desenlace.',
        quotes=[Q('es_celestina', 'La división externa de la obra en actos no tiene un verdadero significado estructural.'), Q('es_celestina', 'Segunda parte: tema de la venganza. Segunda noche de amor. Muerte de Calisto, suicidio de Melibea. Llanto de Pleberio.'), Q('es_celestina', 'La repetición de motivos trae la simetría que ordena la obra.'), Q('en_celestina', 'When he dies in an accident, she commits suicide.')]))
    P.append(dict(text='Cuatro personajes\nCelestina es el personaje más sugestivo, vívido y hedonista, avara y vital, y acabó por dar título a la obra. Calisto es un joven de la alta sociedad a quien solo le importa satisfacer sus deseos; no tiene verdaderas crisis, es egoísta. Melibea es una joven vehemente que pasa de la resistencia a la entrega sin apenas dudas; se siente esclava de una hipocresía que se le ha inculcado en casa. Lucrecia, criada de Melibea, finge odiar a Calisto cuando en realidad envidia a su ama. La crítica señala que Rojas gusta de crear los personajes en parejas y que un rasgo común de señores y criados es el individualismo, el egocentrismo y la falta de altruismo. Calisto y Melibea hablan un lenguaje ideal y literario que puede interpretarse como burla del lenguaje amoroso.',
        quotes=[Q('es_celestina', 'Celestina es el personaje más sugestivo de la obra y la protagonista indiscutible de la misma'), Q('es_celestina', 'Calisto es un joven de la alta sociedad a quien solamente le preocupa satisfacer sus deseos'), Q('es_celestina', 'Melibea es una joven vehemente'), Q('es_celestina', 'Fernando de Rojas gusta de crear los personajes en parejas'), Q('en_celestina', 'Though the two use the rhetoric of courtly love, sex — not marriage — is their aim.')]))
    P.append(dict(text='Celestina, la hechicera\nLa magia en La Celestina tiene opiniones contrapuestas: para Lida de Malkiel es una nota de la época un tanto ingenua; para Petriconi, Maravall y Russell cumple una función importante en el desarrollo. Para el antropólogo Carmelo Lisón Tolosana, Celestina es un híbrido de hechicera y bruja que vive de su oficio y que sabe leer los agüeros y activar el poder de líquidos, hilados y palabras. Julio Caro Baroja no la considera híbrida, sino un ejemplo de hechicera, porque las brujas actuaban en el campo y las hechiceras en la ciudad. El hecho esencial para el argumento es el conjuro a Plutón con el que Celestina logra que Melibea se enamore de Calisto, unido a sus dotes de dialéctica.',
        quotes=[Q('es_celestina', 'En lo referente al tema de la magia, hay opiniones contrapuestas en cuanto a su importancia dentro de la obra.'), Q('es_celestina', 'Según el antropólogo español Carmelo Lisón Tolosana, el personaje de Celestina constituye el tipo universal de la vieja bruja, hechicera y alcahueta'), Q('es_celestina', 'mediante la magia de un conjuro a Plutón, unido a sus habilidades dialécticas, logra asimismo que Melibea se enamore de Calisto'), Q('en_celestina', 'The name Celestina has become synonymous with "procuress" in Spanish')]))
    P.append(dict(text='Censura y fortuna\nLos moralistas atacaron La Celestina desde muy temprano porque, lejos de reprender a los locos enamorados como decía su título, incitaba a amores ilícitos. El primero en desaconsejar su lectura fue Juan Luis Vives en 1524. Sin embargo, no apareció en el Índice hasta 1632, y aun entonces solo fue expurgada; en 1792 se decidió prohibirla. La obra sobrevivió a esa desconfianza y sigue considerándose una de las grandes de la literatura española. La fuente inglesa destaca que hay incluso una revista dedicada solo a ella, Celestinesca, y que suele considerarse el final del periodo medieval y el comienzo del Renacimiento literario.',
        quotes=[Q('es_celestina', 'El primero en desaconsejar la lectura de La Celestina fue Juan Luis Vives'), Q('es_celestina', 'La Celestina no apareció en el Index hasta 1632, y aun entonces únicamente fue sometida a expurgo.'), Q('en_celestina', 'is even the single topic of a Spanish literary journal, Celestinesca'), Q('en_celestina', 'La Celestina is usually regarded as marking the end of the medieval period and the beginning of the renaissance in Spanish literature.')]))
    P.append(dict(text='Cuatro ediciones en 1554\nSe conservan cuatro ediciones distintas del Lazarillo, las cuatro de 1554, impresas en Burgos, Amberes, Alcalá de Henares y Medina del Campo, y parece que las más antiguas son las de Burgos y Medina. Del ejemplar de Medina del Campo, hallado en 1992 emparedado en una casa de Barcarrota (Badajoz), solo hay uno. Es muy probable que existiese una edición más antigua, de 1553 o 1552, cuyo éxito generase las cuatro simultáneas. La fuente inglesa coincide en que las ediciones más antiguas son de 1554 y en que la obra se publicó anónima por su contenido anticlerical.',
        quotes=[Q('es_lazarillo', 'Se conservan cuatro primeras ediciones distintas de la obra, las cuatro del año 1554'), Q('es_lazarillo', 'apareció en 1992 emparedado en una casa de la Plaza de Nuestra Señora de Soterraño de la localidad pacense de Barcarrota'), Q('es_lazarillo', 'es muy probable que existiese una edición más antigua, de 1553 o 1552'), Q('en_lazarillo', 'is a Spanish novella, published anonymously because of its anticlerical content')]))
    P.append(dict(text='Un autor desconocido\nA lo largo de los siglos se han postulado varios autores del Lazarillo. En 1605 el fray José de Sigüenza lo atribuyó a fray Juan de Ortega, general de los jerónimos, atribución defendida por Bataillon; en 1607 se mencionó a Diego Hurtado de Mendoza; a fines del siglo XIX se relacionó al autor con el círculo erasmista de los hermanos Valdés; y otras candidaturas son las de Sebastián de Horozco, Lope de Rueda o Francisco Cervantes de Salazar. Ninguna cuenta con consenso. Lo que se deduce de la obra es que su autor era un hombre culto y probablemente simpatizante de las ideas erasmistas, lo que explicaría el anonimato en un contexto de persecución inquisitorial.',
        quotes=[Q('es_lazarillo', 'En 1605 el fraile José de Sigüenza de la Orden de San Jerónimo atribuyó la autoría de esta obra al también jerónimo fray Juan de Ortega'), Q('es_lazarillo', 'se dice que Diego Hurtado de Mendoza «compuso [...] el libro de entretenimiento llamado Lazarillo de Tormes»'), Q('es_lazarillo', 'relaciona al autor de Lazarillo con el círculo erasmista de los hermanos Valdés'), Q('es_lazarillo', 'Probablemente el autor fue simpatizante de las ideas erasmistas'), Q('en_lazarillo', 'is a Spanish novella, published anonymously because of its anticlerical content')]))
    P.append(dict(text='Una carta a «Vuestra Merced»\nLa obra es una larga epístola que el «autor» envía a un corresponsal anónimo al que trata de «Vuestra Merced». La fuente propone que sería un visitador o su notario eclesiástico, si el contexto es una visita pastoral a la parroquia de San Salvador de Toledo, en la que se investiga el «caso», es decir, los rumores sobre la relación del arcipreste con la mujer de Lázaro. La carta es así un alegato autojustificativo: Lázaro cuenta su vida para explicar cómo ha llegado a esa situación. Está dividida en siete tratados y narrada en primera persona por un niño de origen humilde nacido, como Amadís, junto a un río, el Tormes.',
        quotes=[Q('es_lazarillo', 'La obra es, en realidad, una larga epístola que el "autor" envía a un corresponsal anónimo'), Q('es_lazarillo', 'Está dividida en siete tratados y cuenta en primera persona la historia de Lázaro'), Q('ws_lazarillo1', 'Pues sepa vuestra merced, ante todas cosas, que a mí me llaman Lázaro de Tormes'), Q('en_lazarillo', 'Lázaro develops his cunning while serving the blind beggar and several other masters')]))
    P.append(dict(text='El toro de piedra\nEl primer tratado cuenta el nacimiento de Lázaro dentro del río Tormes y su entrada al servicio de un ciego. Al salir de Salamanca, en la puente hay un animal de piedra con forma de toro, y el ciego le manda acercar el oído para oír un gran ruido: «afirmó recio la mano y dióme una gran calabazada en el diablo del toro». Le dice: «Necio, aprende, que el mozo del ciego un punto ha de saber más que el diablo». Lázaro despierta de su simpleza como un niño dormido y decide avivar el ojo. La escena condensa el método de la novela: una burla física, un aprendizaje, la lección con tono de sentencia. Lázaro acabará devolviéndole la burla al ciego y dejándolo ante un pilar de piedra.',
        quotes=[Q('ws_lazarillo1', 'Mi nacimiento fué dentro del río Tormes'), Q('ws_lazarillo1', 'afirmó recio la mano y dióme una gran calabazada en el diablo del toro'), Q('ws_lazarillo1', 'Necio, aprende, que el mozo del ciego un punto ha de saber más que el diablo.'), Q('ws_lazarillo1', 'Parescióme que en aquel instante desperté de la simpleza'), Q('es_lazarillo', 'Es despertado a la maldad del mundo por la cornada de un toro de piedra')]))
    P.append(dict(text='El escudero y la honra\nEl tratado tercero presenta al amo más memorable: un escudero pobre que aparenta lo que no tiene. Lázaro, que busca comida, comprende pronto la miseria de la casa vacía: «Finalmente, ella parecía casa encantada». El escudero dice haber almorzado y que «el hartar es de los puercos y el comer regladamente es de los hombres de bien», y Lázaro responde entre sí: «¡Maldita tanta medicina y bondad como aquestos mis amos que yo hallo hallan en la hambre!». Más adelante comenta, tras verlo salir bien vestido: ¡cuántos de estos debéis de tener por el mundo, «que padecen por la negra que llaman honra lo que por vos no sufrirían!». La crítica ve en este amo el idealismo soñador y orgulloso del hidalgo arruinado que luego retomará Cervantes.',
        quotes=[Q('ws_lazarillo3', 'Finalmente, ella parecía casa encantada.'), Q('ws_lazarillo3', 'el hartar es de los puercos y el comer regladamente es de los hombres de bien'), Q('ws_lazarillo3', 'que padecen por la negra que llaman honra lo que por vos no sufrirían!'), Q('es_lazarillo', 'el idealismo soñador y orgulloso del escudero pobre, un personaje al parecer folclórico luego retomado por Cervantes')]))
    P.append(dict(text='Un final ambiguo\nLos últimos tratados son breves: Lázaro sirve a un capellán, a un maestro de hacer panderos y a un alguacil, y se hace aguador; consigue por fin el cargo de pregonero gracias al arcipreste de San Salvador, que le ofrece una casa y la oportunidad de casarse con una de sus criadas para disipar los rumores sobre él. Lázaro sufre la infidelidad con paciencia y termina la carta con un alegato cínico que ridiculiza la literatura idealista del momento. Afirma que ha alcanzado la felicidad, pero para ello ha tenido que perder su honra. El final no resuelve: el lector no sabe si cree o no a Lázaro, y esa ambigüedad es parte de la novedad de la obra.',
        quotes=[Q('es_lazarillo', 'Por último consigue el cargo de pregonero gracias al arcipreste de la iglesia toledana de San Salvador'), Q('es_lazarillo', 'y con ello termina la carta, un cínico alegato autojustificativo que ridiculiza la literatura idealista del momento'), Q('es_lazarillo', 'Lázaro afirma que ha alcanzado la felicidad, pero para ello ha debido perder su honra'), Q('en_lazarillo', 'Lázaro develops his cunning')]))
    P.append(dict(text='Rasgos del género picaresco\nEl Lazarillo es precursor de la novela picaresca por el realismo, la narración en primera persona, la estructura itinerante, el servicio a varios amos y la ideología moralizante y pesimista. El género se configura definitivamente con el Guzmán de Alfarache (1599) de Mateo Alemán. Sus rasgos son: un protagonista pícaro, de muy bajo rango, que aspira a mejorar y recurre al engaño; la estructura de falsa autobiografía; el determinismo, pues el pícaro fracasa siempre; la ideología moralizante y pesimista, ligada a la predicación de ejemplos; la intención satírica; y el realismo incluso naturalista. La picaresca nació como sátira de las instituciones degradadas de la España imperial y de las narraciones idealizadoras del Renacimiento.',
        quotes=[Q('es_lazarillo', 'Esta obra es considerada precursora de la novela picaresca'), Q('es_lazarillo', 'se configurará definitivamente con el Guzmán de Alfarache (1599) de Mateo Alemán'), Q('es_picaresca', 'Estructura de falsa autobiografía.'), Q('es_picaresca', 'Determinismo. Aunque el pícaro intenta mejorar de condición social, fracasa siempre'), Q('es_picaresca', 'La novela picaresca nació como sátira crítica, por un lado, de las instituciones degradadas de la España imperial')]))
    P.append(dict(text='Erasmismo y censura\nEl Lazarillo es un esbozo irónico y despiadado de la sociedad, de la que muestra los vicios y actitudes hipócritas, sobre todo los de clérigos y religiosos. El erasmismo, corriente del humanismo renacentista centrada en las ideas de Erasmo de Róterdam, criticaba la corrupción del clero, la piedad supersticiosa y los aspectos exteriores de la religiosidad, y prefería una religiosidad interior. Apoyado por Carlos V, tuvo gran predicamento hasta que las tensiones entre católicos y protestantes provocaron un clima de sospechas. En ese clima, la Inquisición prohibió el Lazarillo y, más tarde, permitió su publicación una vez expurgada; los tratados cuarto y quinto, el del mercedario y el buldero, sufrieron la poda de la censura.',
        quotes=[Q('es_lazarillo', 'Lazarillo de Tormes es un esbozo irónico y despiadado de la sociedad del momento'), Q('es_erasmismo', 'Critica la corrupción del clero, especialmente la del clero regular, la piedad supersticiosa'), Q('es_erasmismo', 'Apoyado por el emperador Carlos V, el Erasmismo tuvo gran predicamento en toda Europa'), Q('es_lazarillo', 'Esto motivó que la Inquisición la prohibiera y que, más tarde, permitiera su publicación, una vez expurgada.')]))
    return P


